# Lattice/ideal arithmetic in a quadratic field Q(w), w^2 = T*w - NN; elements (a, b) = a + b*w with rational a, b.
from fractions import Fraction as F
from math import gcd
def mul(x, y):
    a, b = F(x[0]), F(x[1]); c, d = F(y[0]), F(y[1])
    return (a*c - b*d*NN, a*d + b*c + b*d*T)
def conj(x):
    a, b = F(x[0]), F(x[1]); return (a + b*T, -b)
def nrm(x):
    a, b = F(x[0]), F(x[1]); return a*a + a*b*T + b*b*NN
def inv(x):
    n = nrm(x); c = conj(x); return (c[0]/n, c[1]/n)
def _egcd(a, b):
    if b == 0: return (abs(a), (1 if a >= 0 else -1), 0)
    g, x, y = _egcd(b, a % b); return (g, y, x - (a // b) * y)
def hnf(vs):
    """canonical Z-basis ((h,0),(c,e)) of the rank-2 lattice spanned by vs (rational vectors)"""
    den = 1
    for v in vs:
        for t in v:
            q = F(t).denominator; den = den * q // gcd(den, q)
    iv = [(int(F(v[0]) * den), int(F(v[1]) * den)) for v in vs]
    e = 0; u = (0, 0)
    for v in iv:
        if v[1] == 0: continue
        if e == 0:
            e = abs(v[1]); u = v if v[1] > 0 else (-v[0], -v[1]); continue
        g, s, t = _egcd(e, v[1]); u = (s*u[0] + t*v[0], s*u[1] + t*v[1]); e = g
    assert e != 0, "rank < 2"
    h = 0
    for v in iv:
        k = v[1] // e; h = gcd(h, v[0] - k*u[0])
    assert h != 0, "rank < 2"
    return ((F(h, den), F(0)), (F(u[0] % h, den), F(e, den)))
def basis(L): return [L[0], L[1]]
def ideal(gens, rb=((1, 0), (0, 1))):
    """the R-module generated by gens, R the order with Z-basis rb"""
    return hnf([mul(g, r) for g in gens for r in rb])
def lprod(L, M): return hnf([mul(x, y) for x in basis(L) for y in basis(M)])
def lsum(L, M): return hnf(basis(L) + basis(M))
def contains(L, M): return lsum(L, M) == L          # M subset of L
def covol(L): return abs(L[0][0] * L[1][1])
def scale(x, L): return hnf([mul(x, v) for v in basis(L)])
def _dual(L):
    (a, b), (c, d) = L; det = a*d - b*c
    # rows of (B^{-1})^T
    return hnf([(d/det, -c/det), (-b/det, a/det)])
def lint(L, M): return _dual(lsum(_dual(L), _dual(M)))
def colon(R, I):
    """(R : I) = {x : x I subset R} for lattices R (an order) and I"""
    res = None
    for b in basis(I):
        Lb = scale(inv(b), R)
        res = Lb if res is None else lint(res, Lb)
    return res
